'use client';
import { useState, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';

export function QueryProvider({ children }: { children: ReactNode }) {
  const [queryClient] = useState(() =>
    new QueryClient({
      defaultOptions: {
        queries: {
          staleTime: 60_000,
          retry: 2,
          refetchOnWindowFocus: true,
        },
        mutations: { retry: 0 },
      },
    }),
  );

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      {process.env.NODE_ENV === 'development' && <ReactQueryDevtools />}
    </QueryClientProvider>
  );
}

import { useQuery } from '@tanstack/react-query';

async function getSearchResults(query: string, signal: AbortSignal) {
  const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal });
  if (!response.ok) {
    throw new Error(`Search failed: ${response.status}`);
  }
  return response.json() as Promise<SearchResult[]>;
}

function SearchResults({ query }: { query: string }) {
  const result = useQuery({
    queryKey: ['search', query],
    queryFn: ({ signal }) => getSearchResults(query, signal),
    enabled: query.trim().length >= 2,
  });

  if (result.isPending) return <SearchSkeleton />;
  if (result.isError) return <p role="alert">{result.error.message}</p>;
  return <ResultList results={result.data} />;
}

