  if (isPending) return <Spinner />;
  if (isError) return <p>Không tải được người dùng.</p>;
  return <div>{data.name}</div>;
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

export function useAddTodo() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: addTodoApi,
    onSuccess: async () => {
      // Đánh dấu stale; active matching queries refetch ở background mặc định
      await queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  });
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

type Todo = { id: string; title: string };

export function useRenameTodo() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: renameTodoApi,
    onMutate: async (next: Todo) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] });
      const previous = queryClient.getQueryData<Todo[]>(['todos']);
      queryClient.setQueryData<Todo[]>(['todos'], old =>
        old?.map(todo => todo.id === next.id ? next : todo)
      );
      return { previous };
    },
    onError: (_error, _next, context) => {
      queryClient.setQueryData(['todos'], context?.previous);
    },
    onSettled: () => {
      return queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  });
}

import { queryOptions, useQuery, useQueryClient } from '@tanstack/react-query';

type Project = { id: string; name: string };

export const projectQueries = {
  all: () => ['projects'] as const,
  detail: (id: string) =>
    queryOptions({
      queryKey: ['projects', 'detail', id] as const,
      queryFn: async (): Promise<Project> => {
        const response = await fetch(`/api/projects/${id}`);
        if (!response.ok) throw new Error('Không tải được project');
        return response.json();
      },
      staleTime: 60_000,
    }),
};

export function ProjectName({ id }: { id: string }) {
  const project = useQuery(projectQueries.detail(id));
  if (project.isPending) return <span>Đang tải...</span>;
  if (project.isError) return <span>Tải thất bại</span>;
  return <strong>{project.data.name}</strong>;
}

export function ProjectLink({ id }: { id: string }) {
  const queryClient = useQueryClient();
  return (
    <a
      href={`/projects/${id}`}
      onMouseEnter={() => queryClient.prefetchQuery(projectQueries.detail(id))}
    >
      Xem project
    </a>
  );
}

import { useQueries, useQuery } from '@tanstack/react-query';

// Số lượng động: tất cả project được fetch song song
function ProjectCards({ ids }: { ids: string[] }) {
  const projects = useQueries({
    queries: ids.map(id => projectQueries.detail(id)),
  });

  return projects.map((project, index) => (
    <div key={ids[index]}>
      {project.isPending ? 'Đang tải...' : project.data?.name}
    </div>
  ));
}

// Query thứ hai thật sự cần user.id từ query thứ nhất
function UserProjects({ email }: { email: string }) {
  const user = useQuery({
    queryKey: ['users', 'by-email', email],
    queryFn: () => getUserByEmail(email),
  });

  const projects = useQuery({
    queryKey: ['projects', 'by-user', user.data?.id],
    queryFn: () => getProjectsByUser(user.data!.id),
    enabled: Boolean(user.data?.id),
  });

  return <ProjectList projects={projects.data ?? []} />;
}

import { keepPreviousData, useQuery } from '@tanstack/react-query';
import { useState } from 'react';

function ProjectsTable() {
  const [page, setPage] = useState(1);
  const projects = useQuery({
    queryKey: ['projects', { page }],
    queryFn: () => fetchProjectsPage(page),
    placeholderData: keepPreviousData,
  });

  return (
    <>
      <ProjectRows rows={projects.data?.items ?? []} />
      {projects.isFetching && <span>Đang cập nhật...</span>}
      <button disabled={page === 1} onClick={() => setPage(p => p - 1)}>Trước</button>
      <button
        disabled={projects.isPlaceholderData || !projects.data?.hasMore}
        onClick={() => setPage(p => p + 1)}
      >
        Sau
      </button>
    </>
  );
}

import { useInfiniteQuery } from '@tanstack/react-query';

type FeedPage = {
  items: Array<{ id: string; title: string }>;
  nextCursor: string | null;
};

function Feed() {
  const feed = useInfiniteQuery({
    queryKey: ['feed'],
    initialPageParam: null as string | null,
    queryFn: ({ pageParam }) => fetchFeed({ cursor: pageParam }),
    getNextPageParam: (lastPage: FeedPage) => lastPage.nextCursor ?? undefined,
  });

  const items = feed.data?.pages.flatMap(page => page.items) ?? [];

  return (
    <>
      <ul>{items.map(item => <li key={item.id}>{item.title}</li>)}</ul>
      <button
        disabled={!feed.hasNextPage || feed.isFetchingNextPage}
        onClick={() => feed.fetchNextPage()}
      >
        {feed.isFetchingNextPage ? 'Đang tải...' : feed.hasNextPage ? 'Tải thêm' : 'Đã hết'}
      </button>
    </>
  );
}

import {
  useInfiniteQuery,
  useMutation,
  useQueries,
  useQuery,
  useQueryClient,
  useSuspenseQuery,
} from '@tanstack/react-query';

function DataDashboard({ id, roomIds }: { id: string; roomIds: string[] }) {
  // 1 resource, component tự xử lý pending/error
  const user = useQuery({
    queryKey: ['user', id],
    queryFn: () => getUser(id),
  });

  // Đặt component dưới <Suspense> + Error Boundary; data luôn tồn tại
  const { data: settings } = useSuspenseQuery({
    queryKey: ['settings'],
    queryFn: getSettings,
  });

  // Số lượng resource động, chạy song song
  const messages = useQueries({
    queries: roomIds.map(roomId => ({
      queryKey: ['messages', roomId],
      queryFn: () => getMessages(roomId),
    })),
  });

  // Nhiều page của cùng feed
  const feed = useInfiniteQuery({
    queryKey: ['feed'],
    initialPageParam: null as string | null,
    queryFn: ({ pageParam }) => getFeed(pageParam),
    getNextPageParam: last => last.nextCursor ?? undefined,
  });

  // Ghi dữ liệu + điều phối cache
  const queryClient = useQueryClient();
  const saveUser = useMutation({
    mutationKey: ['users', 'save'],
    mutationFn: updateUser,
    onSuccess: savedUser => {
      queryClient.setQueryData(['user', savedUser.id], savedUser);
    },
  });

  return <DashboardView {...{ user, settings, messages, feed, saveUser }} />;
}

import { useIsFetching, useIsMutating, useMutationState } from '@tanstack/react-query';

export function GlobalNetworkStatus() {
  const fetchingCount = useIsFetching();
  const mutatingCount = useIsMutating();

  if (fetchingCount + mutatingCount === 0) return null;
  return (
    <div role="status" aria-live="polite">
      Đang đồng bộ {fetchingCount + mutatingCount} tác vụ…
    </div>
  );
}

export function PendingUserNames() {
  const pendingNames = useMutationState<string>({
    filters: { mutationKey: ['users', 'save'], status: 'pending' },
    select: mutation => {
      const variables = mutation.state.variables as { name: string };
      return variables.name;
    },
  });

  return pendingNames.map((name, index) => (
    <span key={`${name}-${index}`} aria-busy="true">{name} đang lưu…</span>
  ));
}

